harness:
#include <iostream>
#include <vector>

std::vector<std::vector<int>>
Transpose(const std::vector<std::vector<int>>& m);

int main()
{
    int r, c;
    while (std::cin >> r >> c)
    {
        std::vector<std::vector<int>> m(r, std::vector<int>(c));
        for (int i = 0; i < r; i++)
        {
            for (int j = 0; j < c; j++)
            {
                std::cin >> m[i][j];
            }
        }
        auto t = Transpose(m);
        std::cout << t.size() << "x" << (t.empty() ? 0 : t[0].size()) << "\n";
        for (const auto& row : t)
        {
            for (std::size_t j = 0; j < row.size(); j++)
            {
                std::cout << row[j] << (j + 1 < row.size() ? " " : "");
            }
            std::cout << "\n";
        }
    }
    return 0;
}

