"""Random rectangular matrices, usually not square."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    r, c = rng.randint(1, 5), rng.randint(1, 5)
    rows = [" ".join(str(rng.randint(-9, 9)) for _ in range(c)) for _ in range(r)]
    return {"name": "a %dx%d matrix #%d" % (r, c, index),
            "stdin": "%d %d\n%s\n" % (r, c, "\n".join(rows))}
